[CmdletBinding()]
param([string]$ProjectRoot=(Get-Location).Path,[string]$TraceabilityPath='',[switch]$RequireTraceability)
$ErrorActionPreference='Stop';$errors=[System.Collections.Generic.List[string]]::new()
function Read-Yaml([string]$Path){$code="import sys,yaml,json,pathlib; print(json.dumps(yaml.safe_load(pathlib.Path(sys.argv[1]).read_text(encoding=chr(117)+chr(116)+chr(102)+chr(45)+chr(56))), ensure_ascii=False, default=str))";$o=& python -c $code $Path 2>&1;if($LASTEXITCODE-ne 0){throw "Cannot parse YAML: $Path`n$($o-join"`n")"};return ($o-join"`n")|ConvertFrom-Json}
$rootPath=(Resolve-Path -LiteralPath $ProjectRoot).Path;if([string]::IsNullOrWhiteSpace($TraceabilityPath)){$TraceabilityPath=Join-Path $rootPath '.spec/traceability.yaml'}elseif(-not [IO.Path]::IsPathRooted($TraceabilityPath)){$TraceabilityPath=Join-Path $rootPath $TraceabilityPath};if(-not(Test-Path -LiteralPath $TraceabilityPath -PathType Leaf)){if($RequireTraceability){Write-Error "traceability file not found: $TraceabilityPath";exit 1};Write-Output "Traceability validation skipped: no file at $TraceabilityPath";exit 0}
try{$trace=Read-Yaml $TraceabilityPath}catch{Write-Error $_;exit 1};if([string]::IsNullOrWhiteSpace([string]$trace.projectId)){$errors.Add('traceability.projectId is required')};$required=@('linkId','from','relation','to','lifecycle','recordedBy','recordedAt');$relations=@('derived-from','satisfies','implements','verified-by','released-as','observed-by','caused-by','fixes','supersedes','blocks','routes-to');$lifecycles=@('CREATE','CHANGE','DEFECT','REFACTOR','INCIDENT','OPTIMIZE');$links=@($trace.links);if($links.Count-eq 0){$errors.Add('traceability.links is empty')};$ids=[System.Collections.Generic.HashSet[string]]::new();foreach($link in $links){foreach($f in $required){if($null-eq $link.$f-or [string]::IsNullOrWhiteSpace([string]$link.$f)){$errors.Add("link missing required field: $f")}};$id=[string]$link.linkId;if($id-and -not $ids.Add($id)){$errors.Add("duplicate linkId: ${id}")};$relation=[string]$link.relation;if($relation-notin $relations){$errors.Add("invalid relation for ${id}: ${relation}")};$lc=[string]$link.lifecycle;if($lc-notin $lifecycles){$errors.Add("invalid lifecycle for ${id}: ${lc}")}}
if($errors.Count-gt 0){$errors|%{Write-Error $_};Write-Output "Traceability validation failed: $($errors.Count) error(s)";exit 1};Write-Output "Traceability validation passed: $($links.Count) link(s)";exit 0